from pptx import Presentation
import sys
import traceback

try:
    print("Opening presentation...")
    prs = Presentation('/root/Awesome-Agent-Papers.pptx')
    print(f"Total slides: {len(prs.slides)}")

    for i, slide in enumerate(prs.slides):
        print(f"\n--- Slide {i+1} ---")
        try:
            print(f"Number of shapes: {len(slide.shapes)}")
            for j, shape in enumerate(slide.shapes):
                print(f"  Shape {j}: {type(shape)}")
                try:
                    if shape.has_text_frame:
                        print(f"    Text: '{shape.text_frame.text}'")
                except Exception as e:
                    print(f"    Error reading text: {e}")
        except Exception as e:
            print(f"Error accessing shapes on slide {i+1}: {e}")
            traceback.print_exc()

except Exception as e:
    print(f"Global Error: {e}")
    traceback.print_exc()

